import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { primitives } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.position.set(0, -2.85, 0.26);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Textured plane
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously
  let loadedTexture = null;
  ctx.textureLoader.loadTexture('/prism-assets/chrome/brushed-metal.map.png')
    .then(tex => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const fontSize = (item.typography?.fontSize) ?? 42;
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: config.visualSpec?.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    // Slightly in front of the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives if any (none in this spec)
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handler);
    }
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();
    // Dispose texture if loaded
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
  };

  return root;
}
